35	import type { AppLocale } from "types/i18n";
36	import {
37	  MONTHS_URL as DEFAULT_MONTHS_URL,
38	  MIN_VALID_YEAR,
39	  MAX_VALID_YEAR,
40	} from "@utils/constants";
41	import { connection } from "next/server";
42	import { cache } from "react";
43	
44	const NoEventsFound = dynamic(
45	  () => import("@components/ui/common/noEventsFound")
46	);
47	
48	// React cache() keys on argument identity. generateMetadata and Page each
49	// create their own {place, from, to, size} object literal, so wrapping
50	// fetchEvents directly would NOT dedupe. This primitive-keyed wrapper solves
51	// it: identical (place, from, to) tuples produce a single cache entry.
52	const MAX_EVENTS_PER_PAGE = 100;
53	const fetchMonthEvents = cache(
54	  async (place: string, from: string, to: string) =>
55	    fetchEvents({ place, from, to, size: MAX_EVENTS_PER_PAGE })
56	);
