58	export async function generateMetadata({
59	  params,
60	}: {
61	  params: Promise<MonthStaticPathParams>;
62	}) {
63	  const locale = (await rootLocale()) as AppLocale;
64	  const t = await getTranslations({ locale, namespace: "Pages.SitemapMonth" });
65	  const tConstants = await getTranslations({
66	    locale,
67	    namespace: "Components.Constants",
68	  });
69	  const tNotFound = await getTranslations({ locale, namespace: "App.NotFound" });
70	  const { town, year, month } = await params;
71	
72	  // Validate required params
73	  if (!town || !year || !month || !isValidPlace(town)) {
74	    return {
75	      title: tNotFound("title"),
76	      description: tNotFound("description"),
77	    };
78	  }
79	
80	  // Validate year is numeric and reasonable
81	  const yearNum = Number(year);
82	  if (!Number.isFinite(yearNum) || yearNum < MIN_VALID_YEAR || yearNum > MAX_VALID_YEAR) {
83	    return {
84	      title: tNotFound("title"),
85	      description: tNotFound("description"),
86	    };
87	  }
88	
89	  const monthLabels = (tConstants.raw("months") as string[]) || [];
90	  const monthIndex = resolveMonthIndexFromSlug(month);
91	  if (monthIndex === null) {
92	    return {
93	      title: tNotFound("title"),
94	      description: tNotFound("description"),
95	    };
96	  }
97	  const canonicalMonthSlug = DEFAULT_MONTHS_URL[monthIndex];
98	  const monthLabel =
99	    monthLabels[monthIndex] || normalizeMonthParam(canonicalMonthSlug).label;
100	
101	  // Probe events to set robots policy: noindex empty months so GSC stops
102	  // flagging them as soft 404 / "Crawled - currently not indexed". Uses the
103	  // metadata-safe fetchEventsForMetadata, not the fetchMonthEvents wrapper
104	  // Page uses below — fetchMonthEvents goes through fetchWithHmac, which
105	  // unconditionally calls connection() and breaks the static shell if
106	  // called from generateMetadata. See docs/incidents/
107	  // 2026-06-13-cachecomponents-metadata-resume-mismatch.md.
108	  const { from, until } = getHistoricDates(
109	    canonicalMonthSlug,
110	    Number(year),
111	    DEFAULT_MONTHS_URL
112	  );
113	  const fromStr = from.toISOString().split("T")[0];
114	  const toStr = until.toISOString().split("T")[0];
115	
116	  // Place lookup and the events probe are independent — parallelize instead
117	  // of awaiting sequentially.
118	  const [place, events] = await Promise.all([
119	    // Tolerate backend 5xx for place lookup (cosmetic; town slug is an
120	    // acceptable fallback). Prevents archive 500s from intermittent backend
121	    // errors — the main 5xx source per GSC on /sitemap/<town>/<year>/<month>.
122	    fetchPlaceBySlugForMetadata(town).catch(() => null),
123	    fetchEventsForMetadata({
124	      place: town,
125	      from: fromStr,
126	      to: toStr,
127	      size: MAX_EVENTS_PER_PAGE,
128	    }),
129	  ]);
130	  const townLabel = place?.name || town;
131	  const placeType: "region" | "town" =
132	    place?.type === "CITY" ? "town" : "region";
133	  const locationPhrase = formatPlacePreposition(
134	    townLabel,
135	    placeType,
136	    locale,
137	    false
138	  );
139	  // `events === null` means the probe itself failed (upstream outage, bad
140	  // payload) — fail open (no robots override) rather than noindex a page
141	  // that may well have real content; only a confirmed empty result should
142	  // noindex.
143	  const realEventCount =
144	    events && Array.isArray(events.content)
145	      ? (events.content as EventSummaryResponseDTO[]).filter((e) => !e.isAd)
146	        .length
147	      : null;
148	  const robotsOverride = realEventCount === 0 ? "noindex, follow" : undefined;
149	
150	  return buildPageMeta({
151	    title: t("metaTitle", { town: townLabel, month: monthLabel, year }),
152	    description: t("metaDescription", {
153	      locationPhrase,
154	      month: monthLabel,
155	      year,
156	      town: townLabel,
157	    }),
158	    canonical: `${siteUrl}/sitemap/${town}/${year}/${canonicalMonthSlug}`,
159	    locale,
160	    robotsOverride,
161	  });
162	}
163	
164	export default async function Page({
165	  params,
166	}: {
167	  params: Promise<MonthStaticPathParams>;
168	}) {
169	  // Opt out of cacheComponents caching — conditional JsonLdServer rendering
170	  // below depends on event count (jsonData.length, eventsItemList). Without this,
171	  // cached tree shape can differ from replay → "Expected Fragment but got script".
172	  await connection();
173	
174	  const { town, year, month } = await params;
175	  const locale: AppLocale = (await rootLocale()) as AppLocale;
176	  const t = await getTranslations({ locale, namespace: "Pages.SitemapMonth" });
177	  const tConstants = await getTranslations({
178	    locale,
179	    namespace: "Components.Constants",
180	  });
181	  const withLocale = (path: string) => withLocalePath(path, locale);
182	
183	  // Validate required params
184	  if (!town || !year || !month || !isValidPlace(town)) {
185	    notFound();
186	  }
187	
188	  // Validate year is numeric and reasonable
189	  const yearNum = Number(year);
190	  if (!Number.isFinite(yearNum) || yearNum < MIN_VALID_YEAR || yearNum > MAX_VALID_YEAR) {
191	    notFound();
192	  }
193	
194	  const monthLabels = (tConstants.raw("months") as string[]) || [];
195	  const monthIndex = resolveMonthIndexFromSlug(month);
196	  if (monthIndex === null) {
197	    notFound();
198	  }
199	  const canonicalMonthSlug = DEFAULT_MONTHS_URL[monthIndex];
200	  const normalizedIncomingSlug = normalizeMonthParam(month).slug;
201	  if (normalizedIncomingSlug !== canonicalMonthSlug) {
202	    permanentRedirect(withLocale(`/sitemap/${town}/${year}/${canonicalMonthSlug}`));
203	  }
204	  const monthLabel =
205	    monthLabels[monthIndex] || normalizeMonthParam(canonicalMonthSlug).label;
206	
207	  const { from, until } = getHistoricDates(
208	    canonicalMonthSlug,
209	    Number(year),
210	    DEFAULT_MONTHS_URL
211	  );
212	
213	  // Limit JSON-LD to top 50 events to reduce payload size while maintaining SEO value
214	  const MAX_EVENTS_FOR_JSON_LD = 50;
215	
216	  const fromStr = from.toISOString().split("T")[0];
217	  const toStr = until.toISOString().split("T")[0];
218	  const [events, place] = await Promise.all([
219	    fetchMonthEvents(town, fromStr, toStr),
220	    getPlaceBySlug(town).catch(() => null),
221	  ]);
222	  const townLabel = place?.name || town;
223	  const placeType: "region" | "town" =
224	    place?.type === "CITY" ? "town" : "region";
225	  const locationPhrase = formatPlacePreposition(
226	    townLabel,
227	    placeType,
228	    locale,
229	    false
230	  );
231	
232	  const filteredEvents = Array.isArray(events.content)
233	    ? (events.content as EventSummaryResponseDTO[]).filter(
234	      (event) => !event.isAd
235	    )
236	    : [];
237	
238	  // Limit JSON-LD to first N events to reduce payload size
239	  // This still provides good SEO value while keeping response sizes manageable
240	  const eventsForJsonLd = filteredEvents.slice(0, MAX_EVENTS_FOR_JSON_LD);
241	
242	  // Generate event JSON-LD data (limited to avoid payload overflow)
243	  const jsonData = eventsForJsonLd
244	    ? eventsForJsonLd
245	      .map((event) => generateJsonData(event, locale))
246	      .filter((data) => data !== null)
247	    : [];
248	
249	  // Generate structured data for the month archive
250	  const breadcrumbs = [
251	    { name: t("breadcrumbs.home"), url: toLocalizedUrl("/", locale) },
252	    { name: t("breadcrumbs.archive"), url: toLocalizedUrl("/sitemap", locale) },
253	    { name: townLabel, url: toLocalizedUrl(`/sitemap/${town}`, locale) },
254	    {
255	      name: `${monthLabel} ${year}`,
256	      url: toLocalizedUrl(`/sitemap/${town}/${year}/${canonicalMonthSlug}`, locale),
257	    },
258	  ];
259	
260	  // Generate ItemList for events if available (limited to reduce payload)
261	  const eventsItemList =
262	    eventsForJsonLd.length > 0
263	      ? generateItemListStructuredData(
264	        eventsForJsonLd,
265	        t("itemListTitle", { town: townLabel, month: monthLabel, year }),
266	        t("itemListDescription", { town: townLabel, month: monthLabel, year }),
267	        locale,
268	        toLocalizedUrl(`/sitemap/${town}/${year}/${canonicalMonthSlug}`, locale)
269	      )
270	      : null;
271	
272	  // Generate collection page schema
273	  const collectionPageSchema = generateCollectionPageSchema({
274	    title: t("collectionTitle", { town: townLabel, month: monthLabel, year }),
275	    description: t("collectionDescription", {
276	      locationPhrase,
277	      month: monthLabel,
278	      year,
279	    }),
280	    url: toLocalizedUrl(`/sitemap/${town}/${year}/${canonicalMonthSlug}`, locale),
281	    breadcrumbs,
282	    locale,
283	    numberOfItems: filteredEvents.length,
284	    mainEntity: eventsItemList || {
285	      "@type": "Thing",
286	      name: t("itemListTitle", { town: townLabel, month: monthLabel, year }),
287	      description: t("collectionFallbackDescription"),
288	    },
289	  });
290	
291	  return (
292	    <>
293	      {/* Individual Events JSON-LD - kept for backward compatibility */}
294	      {jsonData.length > 0 && (
295	        <JsonLdServer id={`${town}-${month}-${year}-events`} data={jsonData} />
296	      )}
297	
298	      {/* Enhanced Collection Page Schema */}
299	      <JsonLdServer
300	        id={`${town}-${month}-${year}-collection`}
301	        data={collectionPageSchema}
302	      />
303	
304	      {/* Enhanced Events ItemList Schema */}
305	      {eventsItemList && (
306	        <JsonLdServer
307	          id={`${town}-${month}-${year}-itemlist`}
308	          data={eventsItemList}
309	        />
310	      )}
311	
312	      <SitemapLayout>
313	        <SitemapBreadcrumb items={breadcrumbs} />
314	
315	        <header className="text-center">
316	          <h1 className="heading-2 mb-2">
317	            {t("headerTitle", { town: townLabel, month: monthLabel, year })}
318	          </h1>
319	          <p className="body-normal text-foreground/80">
320	            {filteredEvents.length > 0
321	              ? t("headerCount", { count: filteredEvents.length })
322	              : t("headerEmpty")}
323	          </p>
324	        </header>
325	
326	        <section className="w-full">
327	          {filteredEvents.length > 0 ? (
328	            <div className="stack gap-4">
329	              <h2 className="sr-only">{t("srList")}</h2>
330	              {filteredEvents.map((event: EventSummaryResponseDTO) => {
331	                const { formattedStart, formattedEnd } = getFormattedDate(
332	                  event.startDate,
333	                  event.endDate
334	                );
335	                return (
336	                  <article
337	                    key={event.id}
338	                    className="border-b border-border/30 pb-4 w-full"
339	                  >
340	                    <PressableAnchor
341	                      href={withLocale(`/e/${event.slug}`)}
342	                      className="hover:text-primary block group"
343	                      variant="inline"
344	                      prefetch={false}
345	                    >
346	                      <h3 className="heading-4 group-hover:text-primary transition-colors">
347	                        {event.title}
348	                      </h3>
349	                      <div className="flex flex-col sm:flex-row sm:items-center sm:gap-4 body-small text-foreground/80 mt-1">
350	                        <time dateTime={event.startDate}>
351	                          {formattedEnd
352	                            ? `${formattedStart} - ${formattedEnd}`
353	                            : `${formattedStart}`}
354	                        </time>
355	                        {event.location && (
356	                          <>
357	                            <span className="hidden sm:inline">•</span>
358	                            <span>{event.location}</span>
359	                          </>
360	                        )}
361	                        {event.categories && event.categories.length > 0 && (
362	                          <>
363	                            <span className="hidden sm:inline">•</span>
364	                            <span className="text-primary">
365	                              {event.categories[0].name}
366	                            </span>
367	                          </>
368	                        )}
369	                      </div>
370	                      {event.description && (
371	                        <p className="body-small text-foreground mt-2 line-clamp-2">
372	                          {event.description}
373	                        </p>
374	                      )}
375	                    </PressableAnchor>
376	                  </article>
377	                );
378	              })}
379	            </div>
380	          ) : (
381	            <NoEventsFound />
382	          )}
383	        </section>
384	
385	        {filteredEvents.length > 0 && (
386	          <footer className="pt-8 border-t border-border text-center">
387	            <p className="body-small text-foreground/80 mb-4">
388	              {t("footerExplore", { town: townLabel })}
