400	                href={withLocale(`/${town}`)}
401	                className="text-primary hover:text-primary-dark body-small transition-colors"
402	                variant="inline"
403	                prefetch={false}
404	              >
405	                {t("footerCurrentEvents")}
406	              </PressableAnchor>
407	            </div>
408	          </footer>
409	        )}
410	      </SitemapLayout>
411	    </>
412	  );
413	}
